<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/functions.php'; require_login();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=db()->prepare('SELECT r.*,u.name AS reporter FROM reports r JOIN users u ON u.id=r.user_id WHERE r.id=? AND (r.user_id=? OR ?="admin")');$q->execute([$id,current_user_id(),$_SESSION['role']??'user']);$r=$q->fetch();
if(!$r){http_response_code(404);$page_title='Laporan tidak ditemukan';}else{$page_title='Detail Laporan';}
require 'includes/header.php';require 'includes/sidebar.php';
if(!$r): ?><section class="panel empty-state"><h2>Laporan tidak ditemukan</h2><p class="muted">Laporan tidak tersedia atau Anda tidak memiliki akses.</p><a class="btn primary" href="history.php">Kembali ke riwayat</a></section><?php else: ?>
<div class="page-intro"><div><p class="eyebrow">DETAIL LAPORAN #<?= (int)$r['id'] ?></p><h1><?= e($r['title']) ?></h1><p class="muted">Dibuat <?= e(date('d M Y, H:i',strtotime($r['created_at']))) ?></p></div><span class="status <?= strtolower(str_replace(' ','-',$r['status'])) ?>"><?= e($r['status']) ?></span></div><section class="panel detail-grid"><?php if($r['photo_path']): ?><img class="detail-photo" src="<?= e($r['photo_path']) ?>" alt="Foto laporan"><?php endif; ?><div><p class="eyebrow">KATEGORI</p><h3><?= e(report_category_label($r['category'])) ?></h3><p class="eyebrow">LOKASI</p><p><?= e($r['location_name']?:'Belum ditentukan') ?></p><p class="eyebrow">PRIORITAS</p><p><?= e(ucfirst($r['priority'])) ?></p><p class="eyebrow">DESKRIPSI</p><p><?= nl2br(e($r['description'])) ?></p><?php if($r['latitude']!==null && $r['longitude']!==null): ?><p><a class="text-link" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=<?= e($r['latitude']) ?>&mlon=<?= e($r['longitude']) ?>#map=17/<?= e($r['latitude']) ?>/<?= e($r['longitude']) ?>">Lihat koordinat di OpenStreetMap →</a></p><?php endif; ?></div></section><?php endif; require 'includes/footer.php'; ?>